<script>
  import Markdown from '../Markdown/Markdown.svelte'
  import { getQuery } from './image.js'

  let {
    class: klass = '',
    pictureClass = undefined,
    sources,
    alt = '',
    loading = 'lazy',
    fallbackIndex = undefined,
    figure = true,
    figureClass = undefined,
    captionClass = undefined,
    caption = undefined,
    ...rest
  } = $props()

  const fallback = $derived.by(() => {
    if (!sources) throw new Error('Missing prop: sources')
    return sources[fallbackIndex] ?? sources[sources.length - 1]
  })
  const fallbackSrc = $derived(fallback.image.src)
  const fallbackAttrs = $derived(fallback.image.attributes)
</script>

{#if figure}
  <figure class={figureClass} {...rest}>
    <picture class={pictureClass}>
      {#each sources as source}
        <source
          media={getQuery(source)}
          srcset={source.image.srcSet.attribute}
          type={`image/${source.image.options.format}`}
        />
      {/each}

      <img
        class="{klass} image media"
        {alt}
        height={fallbackAttrs.height}
        {loading}
        src={fallbackSrc}
        width={fallbackAttrs.width}
      />
    </picture>
    {#if caption}
      <figcaption class={captionClass}>
        <Markdown content={caption} inline />
      </figcaption>
    {/if}
  </figure>
{:else}
  <picture class={pictureClass} {...rest}>
    {#each sources as source}
      <source
        media={getQuery(source)}
        srcset={source.image.srcSet.attribute}
        type={`image/${source.image.options.format}`}
      />
    {/each}

    <img
      class="{klass} image media"
      {alt}
      height={fallbackAttrs.height}
      {loading}
      src={fallbackSrc}
      width={fallbackAttrs.width}
    />
  </picture>
{/if}
